  KEY `field_orders_organization_id_representative_id_status_index` (`organization_id`,`representative_id`,`status`),
  CONSTRAINT `field_orders_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `field_orders_field_visit_id_foreign` FOREIGN KEY (`field_visit_id`) REFERENCES `field_visits` (`id`) ON DELETE SET NULL,
  CONSTRAINT `field_orders_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `field_orders_representative_id_foreign` FOREIGN KEY (`representative_id`) REFERENCES `users` (`id`),
  CONSTRAINT `field_orders_sales_order_id_foreign` FOREIGN KEY (`sales_order_id`) REFERENCES `sales_orders` (`id`) ON DELETE SET NULL,
